os._exit(0)

class Edge:
    def __init__(self, to, rev, cap, flow):
        self.to = to
        self.rev = rev
        self.cap = cap
        self.flow = flow

class MaxFlow:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, from_node, to_node, cap):
        self.graph[from_node].append(Edge(to_node, len(self.graph[to_node]), cap, 0))
        self.graph[to_node].append(Edge(from_node, len(self.graph[from_node]) - 1, 0, 0))

    def bfs(self, s, t, parent):
        visited = [-1] * self.n
        visited[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for e in self.graph[u]:
                if e.cap - e.flow > 0 and visited[e.to] == -1:
                    visited[e.to] = visited[u]
                    parent[e.to] = u
                    queue.append(e.to)
        return visited[t] != -1

    def dfs(self, u, t, flow, iter_edge, parent):
        if u == t:
            return flow
        for i in range(iter_edge[u], len(self.graph[u])):
            iter_edge[u] = i
            e = self.graph[u][i]
            if e.cap - e.flow > 0 and parent[u] != e.to:
                d = self.dfs(e.to, t, min(flow, e.cap - e.flow), iter_edge, parent)
                if d > 0:
                    e.flow += d
                    self.graph[e.to][e.rev].flow -= d
                    return d
        return 0

    def max_flow(self, s, t):
        maxflow = 0
        parent = [0] * self.n
        iter_edge = [0] * self.n
        while self.bfs(s, t, parent):
            while True:
                flow = self.dfs(s, t, float('inf'), iter_edge, parent)
                if flow == 0:
                    break
                maxflow += flow
            parent = [0] * self.n
        return maxflow

def solution(input_str):
    parts = input_str.strip().split('\n')
    parts = [p for i, p in enumerate(parts) if p and not p.isspace()]

    if len(parts) < 5:
        return "NO"

    n, m = map(int, parts[0].split())
    a = list(map(int, parts[1].split()))
    b = list(map(int, parts[2].split()))

    adj = [[False] * (n + 1) for _ in range(n + 1)]

    line_idx = 3
    for i in range(m):
        line_idx = i + 3
        line = parts[line_idx].split()
        p, q = int(line[0]), int(line[1])
        adj[p][q] = adj[q][p] = True

    total_a = sum(a)
    total_b = sum(b)

    if total_a != total_b:
        return "NO"

    if total_a == 0 and total_b == 0:
        return "YES\n" + "\n".join([f"{' '.join(['0'] * n)}"] * n)

    source = 0
    sink = n + 1

    mf = MaxFlow(n + 2)

    for i in range(1, n + 1):
        mf.add_edge(source, i, a[i-1])
        mf.add_edge(i, sink, b[i-1])

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if adj[i][j] or i == j:
                mf.add_edge(i, j, float('inf'))

    flow = mf.max_flow(source, sink)

    if flow != total_a:
        return "NO"

    distribution = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for e in mf.graph[i]:
            distribution[i][e.to + 1] = e.flow

    result_lines = ["YES"]

    for i in range(1, n + 1):
        row_str = []
        for j in range(1, n + 1):
            row_str.append(str(distribution[i][j]))
        result_lines.append(' '.join(row_str))

    return '\n'.join(result_lines)

