    if k == 0:
        # Check if all non-'?' characters are 'Y'
        for c in s:
            if c == 'N':
                return "NO\n"
        return "YES\n"

    # Use recursion to try all assignments for '?'
    memo = {}

    def max_consecutive_n(i, prev_n):
        if i == n:
            return 0 if prev_n == 0 else prev_n

        if s[i] == '?':
            # Try both Y and N
            key = (i, prev_n)
            if key not in memo:
                result_y = max_consecutive_n(i + 1, 0)
                result_n = max(max_consecutive_n(i + 1, prev_n + 1),
                              result_n if prev_n == 0 else 0)
                memo[key] = (result_n, result_y)

                # Actually we need the maximum across both choices
                return max(max_consecutive_n(i + 1, 0), max(max_consecutive_n(i + 1, prev_n + 1), result_y))
            return memo[key]

