def is_bitonic(arr):
    """Check if an array is bitonic"""
    n = len(arr)
    if n <= 2:
        return True

    # Find the peak - the last position before which values are increasing
    peak = 0
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            peak = i
        else:
            break

    # After peak, values must be strictly decreasing
    for i in range(peak + 1, n):
        if arr[i] >= arr[i-1]:
            return False
    return True

