def solution(input_string: str) -> str:
    lines = input_string.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    result = []

    # Helper to get divisors
    def get_divisors(n):
        divs = set()
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divs.add(i)
                if i != n // i and n // i > 1:
                    divs.add(n // i)
        divs.add(n)
        return sorted(divs)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def count_coprime_pairs(arr):
        n_layout = len(arr)
        count = 0
        for i in range(n_layout):
            if gcd(arr[i], arr[(i + 1) % n_layout]) == 1:
                count += 1
        return count

    for i in range(1, t + 1):
        if i >= len(lines):
            break
        n = int(lines[i].strip())
        divs = get_divisors(n)

        if len(divs) <= 2:
            # Only 1 or 2 divisors - trivial case
            result.append(" ".join(map(str, divs)) + "\n0")
        elif len(divs) <= 10:
            # Brute force for small cases - excellent local optima finding
            best_arr = None
            best_moves = float('inf')

            for perm in permutations(divs):
                moves = count_coprime_pairs(list(perm))
                if moves < best_moves:
                    best_moves = moves
                    best_arr = perm

            arr = list(best_arr)
            result.append(" ".join(map(str, arr)) + f"\n{best_moves}")
        else:
            # For larger divisor sets, use prime-based construction
            # Strategy: group divisors by their prime factors
            primes = []
            d = 2
            temp = n
            while d * d <= temp:
                if temp % d == 0:
                    primes.append(d)
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                primes.append(temp)
            primes.sort(reverse=True)

            used = set()
            arr = []

            # For each prime (largest first), add divisors divisible by this prime
            for p in primes:
                for d in reversed(divs):
                    if d % p == 0 and d not in used:
                        arr.append(d)
                        used.add(d)

            # Add any remaining divisors not divisible by any of the main primes
            for d in divs:
                if d not in used:
                    arr.append(d)
                    used.add(d)

            moves = count_coprime_pairs(arr)
            result.append(" ".join(map(str, arr)) + f"\n{moves}")

    return '\n'.join(result)

