def solution(input_str):
    lines = input_str.strip().split('\n')
    s1, s2, virus = lines[0], lines[1], lines[2]

    n, m, p = len(s1), len(s2), len(virus)

    # If virus is empty, just find regular LCS
    if p == 0:
        from functools import lru_cache

        @lru_cache(None)
        def dp(l, r):
            if l == 0 or r == 0:
                return ""
            if s1[l-1] == s2[r-1]:
                return s1[l-1] + dp(l-1, r-1)
            return max(dp(l-1, r), dp(l, r-1), key=len)

        result = dp(n, m)
        return result if result else "0"

    # Build KMP failure function
    def compute_failure(pattern):
        m = len(pattern)
        failure = [0] * m
        k = 0
        for q in range(1, m):
            while k > 0 and pattern[k] != pattern[q]:
                k = failure[k-1]
            if pattern[k] == pattern[q]:
                k += 1
            failure[q] = k
        return failure

    failure = compute_failure(virus)

    # Build KMP transition table: trans[state][char_code] -> next_state
    trans = [[0] * 26 for _ in range(p + 1)]

    for k in range(p + 1):
        for char_code in range(26):
            char = chr(ord('A') + char_code)
            q = 0
            while q > 0:
                while q > 0 and not (k - failure[k-1] if k > 0 else 0) >= q:
                    q -= 1
                if q == 0 and char not in virus:
                    trans[k][char_code] = 0
                    break
                if k - failure[k-1] if k > 0 else 0 >= q:
                    q += 1
                    if k - failure[k-1] if k > 0 else 0 < q:
                        break
            else:
                if k == p or char not in virus[k:]:
                    trans[k][char_code] = 0
                else:
                    trans[k][char_code] = k + 1

    # Simplified approach: track matched length
    @lru_cache(None)
    def dp(i, j, state):
        if i == n or j == m:
            return ""

        # Option 1: Skip s1[i]
        result1 = dp(i + 1, j, state)

        # Option 2: Skip s2[j]
        result2 = dp(i, j + 1, state)

        # Option 3: Match if possible and don't trigger virus
        if s1[i] == s2[j]:
            new_state = state + 1
            # Check if this creates a virus match
            prefix = virus[:new_state]
            if new_state < p and prefix.endswith(s1[i]):
                pass

            # Simpler: just check if appending character matches virus
            if new_state < p and virus.find(s1[i]) == len(virus) - new_state:
                result_match = dp(i + 1, j + 1, new_state)
                return max(result1, result2, result_match, key=lambda x: len(x) if x else -1)

        return max(result1, result2, key=lambda x: len(x) if x else -1)

    # Run simpler LCS with state tracking
    @lru_cache(None)
    def dp2(i, j, matched):
        if i == n or j == m:
            return ""

        # Skip s1[i]
        res1 = dp2(i + 1, j, matched)

        # Skip s2[j]  
        res2 = dp2(i, j + 1, matched)

        # Try matching
        if s1[i] == s2[j]:
            new_matched = matched + 1
            if new_matched < p:
                # Check if this creates virus
                if virus[:new_matched] == virus[0:matched] + s1[i]:
                    res_match = dp2(i + 1, j + 1, new_matched)
                    return max(res1, res2, res_match, key=lambda x: len(x) if x else -1)
            else:
                # Virus started
                return max(res1, res2, key=lambda x: len(x) if x else -1)

        return max(res1, res2, key=lambda x: len(x) if x else -1)

    result = dp2(n, m, 0)
    return result if result else "0"

