    a = list(map(int, lines[1].split()))

    edges = []
    for i in range(2, 2 + m):
        v1, v2, w = map(int, lines[i].split())
        edges.append((v1, v2, w))

    source = 0
    sink = n + 1

    # Build Dinic's algorithm
    class Dinic:
        def __init__(self, n, capacities):
            self.n = n
            self.capacity = [capacities.get((i, j), 0) for j in range(n)]

        def add_edge(self, u, v, w):
            self.capacity[u].append([v, w, len(self.capacity[v])])
            self.capacity[v].append([u, 0, len(self.capacity[u]) - 1])

    # Build graph for max flow (source->vertex->sink)
    total_edge_weight = sum(w for _, _, w in edges)

    # Build network: source(0) -> vertices(1..n) -> sink(n+1)
    # With vertex edges as forward, plus edges between u,v as intermediate

    # Final implementation: use standard construction
    class MaxFlow:
        def __init__(self, n):
            self.n = n
            self.graph = [[] for _ in range(n)]
            self.level = []

        def add_edge(self, u, v, cap):
            self.graph[u].append([v, cap, len(self.graph[v])])
            self.graph[v].append([u, 0, len(self.graph[u]) - 1])

        def bfs(self, s, t):
            self.level = [-1] * self.n
            self.level[s] = 0
            q = [s]
            while q:
                u = q.pop(0)
                for v, c, _ in self.graph[u]:
                    if c > 0 and self.level[v] < 0:
                        self.level[v] = self.level[u] + 1
                        q.append(v)
            return self.level[t] >= 0

        def dfs(self, u, t, f, ptr):
            if u == t or f == 0:
                return f
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                v, cap, rev = self.graph[u][i]
                if self.level[v] == self.level[u] + 1 and cap > 0:
                    pushed = self.dfs(v, t, min(f, cap), ptr)
                    if pushed > 0:
                        self.graph[u][i][1] -= pushed
                        self.graph[v][rev][1] += pushed
                        return pushed
            return 0

        def max_flow(self, s, t):
            flow = 0
            while self.bfs(s, t):
                ptr = [0] * self.n
                while True:
                    pushed = self.dfs(s, t, float('inf'), ptr)
                    if pushed == 0:
                        break
                    flow += pushed
            return flow

