    for i, wi in enumerate(a):
        mf.add_edge(source, i + 1, wi)
    for u_idx, v_idx, w in edges:
        uf, vf = u_idx, v_idx
        mf.add_edge(uf, vf, w)
        mf.add_edge(vf, uf, w)
