    # The key insight: if n is prime, the game is always bad
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    # If n is prime, the game is bad regardless of coin distribution
    if is_prime(n):
        return '-1'

    # For composite n, there exists a sequence of moves to terminate
    return '1'

