def is_prime_miller_rabin(n):
    """Miller-Rabin primality test"""
    if n < 2:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    for a in [2, 3, 5, 7, 11, 13, 17, 19, 23]:
        if a >= n:
            break
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            pass
        else:
            for _ in range(r - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
    return True

def get_prime_factors(num):
    """Get all distinct prime factors of num"""
    if num < 2:
        return []
    factors = []
    d = num
    i = 2
    while i * i <= d:
        if d % i == 0:
            factors.append(i)
            while d % i == 0:
                d //= i
        i += 1
    if d > 1:
        factors.append(d)
    return factors

