    parts = input_str.split()
    if len(parts) < 2:
        return "-1\n"

    n = int(parts[0])
    x = int(parts[1])

    # n+1 must be prime for cyclic numbers
    p = n + 1

    if not is_prime_miller_rabin(p):
        return "-1\n"

    if p == 2:
        # n=1, need 1 < b < x and b is primitive root mod 2
        # Primitive root condition fails for p=2 since b % 2 == 0

    phi_p = p - 1  # = n
    if phi_p == 0:
        return "-1\n"

    # Get prime factors of phi_p
    factors = get_prime_factors(phi_p)

    largest_b = -1

    # Search for the largest b in range [2, min(x-1, p-1)]
    # Find largest primitive root mod p
    start_b = min(x - 1, p - 1)

    if start_b < 2:
        return "-1\n"

    for b in range(start_b, 1, -1):
        # Check if b is a primitive root mod p
        # b is primitive root if b^(phi_p/q) != 1 (mod p) for all prime factors q of phi_p
        ok = True
        for q in factors:
            exponent = phi_p // q
            if pow(b, exponent, p) == 1:
                ok = False
                break

        if ok:
            largest_b = b
            break

    return str(largest_b) + "\n"

