            return 0

        total_profit = 0
        for height in range(max_height + 1):
            # Calculate fines for choosing this height at this position
            current_fines = 0
            for l, r, x, c in restrictions:
                if l <= pos <= r:
                    if height > x:
                        current_fines += c

            # Calculate profit for this choice
            profit = (height ** 2) + solve(pos + 1, height)
            total_profit = max(total_profit, profit)

        return total_profit

    result = solve(1, h)
    return str(result)

