def solution(input_text):
    lines = input_text.strip().split('\n')
    if not lines or len(lines) < 1:
        return '-1\n'

    try:
        n, m = map(int, lines[0].split())
    except:
        return '-1\n'

    # Parse table A - n rows, each with m values
    A = []
    for i in range(n):
        try:
            A.append(list(map(int, lines[1 + i].split())))
        except:
            return '-1\n'

    # Parse table B - n rows, each with m values
    B = []
    for i in range(n):
        try:
            B.append(list(map(int, lines[1 + n + i].split())))
        except:
            return '-1\n'

    if len(A) != n or len(B) != n:
        return '-1\n'

    if len(A[0]) != m or len(B[0]) != m:
        return '-1\n'

    # If already equal, no sorting needed
    if A == B:
        return '0\n'

    def stable_sort_by_col(table, col):
        """Stable sort table by a specific column (0-indexed)"""
        # Create list of (value, original_index, row)
        indexed = [(table[i][col], i, tuple(table[i])) for i in range(len(table))]
        # Sort by (value, original_index) - gives stable sort
        indexed.sort()
        # Extract rows in sorted order
        return [row for _, _, row in indexed]

    def copy_table(table):
        return [row[:] for row in table]

    def are_equal(t1, t2):
        if len(t1) != len(t2) or len(t1[0]) != len(t2[0]):
            return False
        for i in range(len(t1)):
            if t1[i] != t2[i]:
                return False
        return True

    # Pre-check: each column must have same multiset of values
    possible = True
    for col in range(m):
        vals_a = sorted(A[i][col] for i in range(n))
        vals_b = sorted(B[i][col] for i in range(n))
        if vals_a != vals_b:
            possible = False
            break

    if not possible:
        return '-1\n'

    # Try single column sorts (at most 1500 tries)
    for col in range(m):
        test_B = stable_sort_by_col(copy_table(A), col)
        if are_equal(test_B, B):
            return f'1\n{col + 1}\n'

    # Try pairs of column sorts (at most m² tries)
    for col1 in range(m):
        for col2 in range(m):
            test_B = stable_sort_by_col(stable_sort_by_col(copy_table(A), col1), col2)
            if are_equal(test_B, B):
                return f'2\n{col1 + 1} {col2 + 1}\n'

    return '-1\n'

