def solution(input_str):
    """
    Solve the problem of finding xor sum of ways to reach each island after t days.
    """
    # Parse input
    lines = input_str.strip().split('\n')
    first_line = lines[0].strip().split()
    m = int(first_line[0])
    t = int(first_line[1])
    s = int(first_line[2])

    a_values = list(map(int, lines[1].strip().split()))
    MOD = 1051131
    n = 2 * m

    # Compute full a array
    full_a = a_values[:]
    for i in range(s, n):
        full_a.append((101 * full_a[i - s] - s + 10007) % MOD)
    full_a = full_a[:n]

    def count_set_bits(x):
        return bin(x).count('1')

    # Build transition matrix T[j][i] = ways to move from island j to island i in one day
    # Stay: weight 1 if i == j
    # Move: weight 2^(set_bits(i & j)) if i != j
    T = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                T[i][j] = 1  # Stay
            else:
                T[i][j] = pow(2, count_set_bits(i & j), MOD)

    # Matrix multiplication
    def mat_mul(A, B, mod):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k] == 0:
                    continue
                for j in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Matrix exponentiation
    def mat_pow(A, power, mod):
        size = len(A)
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            result[i][i] = 1
        base = A
        while power:
            if power & 1:
                result = mat_mul(result, base, mod)
            base = mat_mul(base, base, mod)
            power >>= 1
        return result

    # Compute T^t
    Tt = mat_pow(T, t, MOD)

    # Final state: apply T^t to initial state
    result = [0] * n
    for j in range(n):
        for i in range(n):
            result[i] = (result[i] + full_a[j] * Tt[j][i]) % MOD

    # XOR sum
    x = 0
    for v in result:
        x ^= v

    return f"{x}\n"

