        """Map effectiveness to direction keys"""
        return {'U': (1, 0), 'D': (-1, 0), 'L': (0, 1), 'R': (0, -1)}.get(dr, dc) is None or (dr, dc) in [('0', '1'), '1', '0']

    def find_path(x, y):
        # BFS on grid
        target = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 'F':
                    target = (r, c)
                    break
        if not target:
            return []

        queue = deque([(x, y, [])])
        visited = {(x, y)}

        while queue:
            curr_x, curr_y, path = queue.popleft()
            if (curr_x, curr_y) == target:
                return path

            for d in ['U', 'D', 'L', 'R']:
                dr, dc = calculate_direction(d, swapUD, swapLR)
