            if op == 'R':
                # Shift columns right: row becomes [row[-1]] + row[:-1]
                new_matrix = [[row[-1]] + row[:-1] for row in matrix]
                matrix = new_matrix
            elif op == 'L':
                # Shift columns left: row becomes row[1:] + [row[0]]
                new_matrix = [row[1:] + [row[0]] for row in matrix]
                matrix = new_matrix
            elif op == 'D':
                # Shift rows down: [matrix[-1]] + matrix[:-1]
                new_matrix = [matrix[-1]] + matrix[:-1]
                matrix = new_matrix
            elif op == 'U':
                # Shift rows up: matrix[1:] + [matrix[0]]
                new_matrix = matrix[1:] + [matrix[0]]
                matrix = new_matrix
            elif op == 'I':
                # Inverse each row permutation
                new_matrix = []
                for row in matrix:
                    # Create inverse: inverted[val-1] = position + 1
                    inverted = [0] * n
                    for pos_idx, val in enumerate(row):
                        inverted[val - 1] = pos_idx + 1
                    new_matrix.append(inverted)
                matrix = new_matrix
            elif op == 'C':
                # Inverse each column permutation
                n_rows, n_cols = len(matrix), len(matrix[0])
                new_matrix = [[0] * n_cols for _ in range(n_rows)]
                for col_idx in range(n_cols):
                    # Extract column
                    col = [matrix[row_idx][col_idx] for row_idx in range(n_rows)]
                    # Invert
                    inverted = [0] * n_rows
                    for pos_idx, val in enumerate(col):
                        inverted[val - 1] = pos_idx + 1
                    # Fill column
                    for row_idx in range(n_rows):
                        new_matrix[row_idx][col_idx] = inverted[row_idx]
                matrix = new_matrix

        # Format output
        result_lines = []
