def solution(s: str) -> str:
    MOD = 10**9 + 7
    s = s.strip()
    n = len(s)
    pos = 0

    def skip_spaces():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_term() -> tuple:
        """Parse a term and return (value_mod_MOD, string_length)"""
        nonlocal pos
        skip_spaces()

        if pos >= n:
            return (0, 0)

        # Parse first number (required for all terms)
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if pos == start:
            raise ValueError("Expected digit")
        num_str = s[start:pos]
        val = int(num_str)

        skip_spaces()
        if pos >= n:
            return (val, len(num_str))

        if s[pos] == '-':
            # Range concatenation: concatenate all numbers from val to right_val
            pos += 1
            skip_spaces()
            start2 = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            right_val = int(s[start2:pos])

            total_len = 0
            total_val = 0
            for i in range(val, right_val + 1):
                si = str(i)
                total_len += len(si)
                total_val = (total_val * pow(10, len(si), MOD) + i) % MOD

            return (total_val, total_len)

        elif s[pos] == '(':
            # Repetition: repeat the inner expression 'val' times
            pos += 1
            skip_spaces()
            inner_val, inner_len = parse_term()
            skip_spaces()
            if pos < n and s[pos] == ')':
                pos += 1

            if inner_val == 0:
                return (0, 0)

            repeat_val = 0
            repeat_len = 0
            for _ in range(val):
                repeat_len += inner_len
                repeat_val = (repeat_val * pow(10, inner_len, MOD) + inner_val) % MOD

            return (repeat_val, repeat_len)

        # Just a number
        return (val, len(num_str))

    def parse_expr() -> tuple:
        """Parse expression: one or more terms separated by '+'"""
        nonlocal pos
        total_val, total_len = parse_term()

        while pos < n and s[pos] == '+':
            pos += 1
            skip_spaces()
            term_val, term_len = parse_term()
            total_len += term_len
            total_val = (total_val * pow(10, term_len, MOD) + term_val) % MOD

        return (total_val, total_len)

    main_val, _ = parse_expr()
    return str(main_val)

