def find_position(n, k):
    if n <= k:
        return n

    # Identify which iteration m the value n belongs to
    # m = ceil(n / (k + 1))
    m = (n + k) // (k + 1)
    if n <= 0:
        return 0

    first_v = k * (m - 1) + 1
    last_v = k * m + (m - 1)
    prev_sum = (m - 1) * (k + 1)
    pos_in_iter = n - prev_sum

    # If n exceeds the expected bound, iterate again
    while n > first_v + k:
        m += 1
        first_v = k * (m - 1) + 1
        last_v = k * m + (m - 1)
        prev_sum = (m - 1) * (k + 1)
        pos_in_iter = n - (m - 1) * (k + 1)

    if first_v <= n <= last_v:
        # Calculate how many sums are in [first_v, n-1]
        gap_count = count_sums_in_range(first_v, n - 1, k - 2)
        return pos_in_iter - gap_count
    else:
        # n is beyond the expected value, means n is a sum position
        pos = m * (k + 1)
        if n == prev_sum:
            return pos
        return find_last_sum_pos(n, k)


def find_last_sum_pos(n, k):
    m = (n + k) // (k + 1)
