    # This is arithmetic progression, count how many multiples fit
    return 0

from functools import lru_cache

MOD = 10**9 + 7

def solution(input_str):
    n, k, m = map(int, input_str.strip().split())

    if k == 1:
        return str(n)

    @lru_cache(maxsize=None)
    def count_ways(last, visited_mask, steps_left):
        if steps_left == 0:
            return 1

        total = 0
        # Next planet can be at most 'last + m', but not exceeding n
        max_next = min(last + m, n)

        for nxt in range(1, max_next + 1):
            # Check if nxt has been visited
            if not (visited_mask & (1 << (nxt - 1))):
                total = (total + count_ways(nxt, visited_mask | (1 << (nxt - 1)), steps_left - 1)) % MOD

        return total

    # Sum over all possible starting positions
    total = 0
    for start in range(1, n + 1):
        total = (total + count_ways(start, 1 << (start - 1), k - 1)) % MOD

    return str(total)
